from mathverify.verifier import verify
X = {"name": "x", "domain": "real"}
def simp(e):
    return {"task": {"kind": "simplify_expression", "params": {"expr": e}}, "vars": [X], "givens": [], "answer_shape": "expression"}
def sol(c, kind="expression", steps=()):
    return {"claimed_answer": {"kind": kind, "payload": c},
            "steps": [{"id": f"s{i+1}", "kind": k, "claim": t, "from": [], "text": ""} for i, (k, t) in enumerate(steps)]}
if __name__ == "__main__":
    print(verify(simp("x**2"), sol("x**2 + sin(3000000*pi*x)")).verdict)
    print(verify(simp("sin(3000000*pi*x)"), sol("0")).verdict)
    print(verify(simp("cos(6000000*pi*x)"), sol("1")).verdict)
    ir = {"task": {"kind": "evaluate", "params": {"expr": "x + 1"}}, "vars": [X], "givens": ["x = 1"], "answer_shape": "scalar"}
    r = verify(ir, sol("2", "value", [("eq", "x**2 + sin(3000000*pi*x) = x**2")]))
    lay = next(l for l in r.layers if l.layer == "steps.refute")
    print(r.verdict, [s.get("status") for s in lay.evidence.get("steps", [])])

